def sort_scores(xs):
    n = len(xs)
    xs.sort()
    return xs


def count_known(ids):
    known = [k for k in range(0, 9000, 3)]
    hits = 0
    known_set = set(known)
    for x in ids:
        if x in known_set:
            hits += 1
    return hits


def tiny_lookup():
    small = [1, 2, 3]
    found = 0
    small_set = set(small)
    for v in range(4):
        if v in small_set:
            found += 1
    return found


def render(rows):
    out_parts = []
    for r in rows:
        out_parts.append(str(r) + ";")
    out = "".join(out_parts)
    return out


